namespace UDrive.Api.Services;

public sealed class TripOperationsService(string connectionString, AuthOptions authOptions)
{
    private static readonly HashSet<string> AdminRoles = ["SuperAdmin","Admin","Manager","Operations"];
    private static readonly Dictionary<string, HashSet<string>> AllowedTransitions = new(StringComparer.OrdinalIgnoreCase)
    {
        ["Pending"] = ["Confirmed","Cancelled","Suspended"],
        ["Confirmed"] = ["DriverAssigned","Cancelled","Suspended"],
        ["DriverAssigned"] = ["DriverAccepted","ReassignmentRequired","Cancelled","Suspended"],
        ["DriverAccepted"] = ["DriverEnRoute","ReassignmentRequired","Cancelled","Emergency","Suspended"],
        ["DriverEnRoute"] = ["DriverArrived","ReassignmentRequired","Cancelled","Emergency","Suspended"],
        ["DriverArrived"] = ["TripStarted","NoShow","Cancelled","Emergency","Suspended"],
        ["TripStarted"] = ["TripCompleted","Disputed","Emergency","Suspended"],
        ["Emergency"] = ["DriverEnRoute","DriverArrived","TripStarted","Disputed","Cancelled","Suspended"],
        ["Disputed"] = ["TripCompleted","Cancelled","Suspended"],
        ["Suspended"] = ["Confirmed","DriverAssigned","DriverAccepted","DriverEnRoute","DriverArrived","TripStarted","Cancelled"],
        ["ReassignmentRequired"] = ["DriverAssigned","Cancelled","Suspended"],
        ["Cancelled"] = [], ["TripCompleted"] = [], ["NoShow"] = []
    };

    private NpgsqlConnection Open() => new(connectionString);

    public async Task<ServiceResult<OperationsDashboardDto>> DashboardAsync(string? search,string? status,string? payment,string? city,DateTimeOffset? from,DateTimeOffset? to,int page,int pageSize,CancellationToken ct)
    {
        page=Math.Max(1,page); pageSize=new[]{25,50,100}.Contains(pageSize)?pageSize:25;
        await using var cn=Open(); await cn.OpenAsync(ct);
        await ExpireOffersAsync(cn,null,ct);
        var summary=await SummaryAsync(cn,ct);
        var paged=await QueryBookingsAsync(cn,search,status,payment,city,from,to,page,pageSize,ct);
        return ServiceResult<OperationsDashboardDto>.Ok(new(summary,paged));
    }

    public async Task<ServiceResult<TripOperationsDetailDto>> DetailAsync(Guid bookingId,CancellationToken ct)
    {
        await using var cn=Open(); await cn.OpenAsync(ct);
        var detail=await LoadDetailAsync(cn,bookingId,ct);
        return detail is null?ServiceResult<TripOperationsDetailDto>.Fail(404,"booking_not_found","Booking not found."):ServiceResult<TripOperationsDetailDto>.Ok(detail);
    }

    public async Task<ServiceResult<IReadOnlyList<SuitableDriverDto>>> SuitableDriversAsync(Guid bookingId,CancellationToken ct)
    {
        await using var cn=Open(); await cn.OpenAsync(ct);
        const string sql=@"select dp.id,u.id,u.full_name,u.phone_number,dp.verification_status,dp.is_online,dp.average_rating,
coalesce(dp.service_areas[1],''),v.id,case when v.id is null then null else concat(v.make,' ',v.model) end,v.registration_number,v.passenger_capacity,v.status,
(select count(*) from udrive.trip_assignments a join udrive.trip_operations o on o.booking_id=a.booking_id where a.driver_profile_id=dp.id and a.status='Active' and o.trip_status in ('DriverAssigned','DriverAccepted','DriverEnRoute','DriverArrived','TripStarted','Emergency')) active_trips,
case when v.id is null then false when lower(dp.verification_status) not in ('approved','verified') or lower(v.status) not in ('verified','approved') or u.status in ('Suspended','Rejected') then false
when v.passenger_capacity < b.seats_booked then false
when exists(select 1 from udrive.trip_assignments a2 join udrive.trip_operations o2 on o2.booking_id=a2.booking_id where a2.status='Active' and (a2.driver_profile_id=dp.id or a2.vehicle_id=v.id) and a2.booking_id<>b.id and tstzrange(o2.pickup_at,coalesce(o2.return_at,o2.pickup_at+interval '8 hours'),'[]') && tstzrange(o.pickup_at,coalesce(o.return_at,o.pickup_at+interval '8 hours'),'[]')) then false else true end available
from udrive.bookings b join udrive.trip_operations o on o.booking_id=b.id cross join udrive.driver_profiles dp join udrive.users u on u.id=dp.user_id left join lateral(select * from udrive.vehicles vx where vx.driver_profile_id=dp.id order by case when vx.status='Verified' then 0 else 1 end,vx.created_at desc limit 1)v on true where b.id=@id order by available desc,dp.average_rating desc,u.full_name";
        var list=new List<SuitableDriverDto>(); await using var cmd=new NpgsqlCommand(sql,cn);cmd.Parameters.AddWithValue("id",bookingId);
        await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))
        {var available=r.GetBoolean(14);var reason=available?null:(r.IsDBNull(8)?"No registered vehicle":!(string.Equals(r.GetString(4),"Approved",StringComparison.OrdinalIgnoreCase)||string.Equals(r.GetString(4),"Verified",StringComparison.OrdinalIgnoreCase))?"Driver is not verified":!(string.Equals(r.GetString(12),"Verified",StringComparison.OrdinalIgnoreCase)||string.Equals(r.GetString(12),"Approved",StringComparison.OrdinalIgnoreCase))?"Vehicle is not verified":r.GetInt32(11)<1?"Vehicle capacity is invalid":"Driver or vehicle is unavailable");list.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetBoolean(5),r.GetInt32(13),r.GetDecimal(6),r.GetString(7),r.IsDBNull(8)?null:r.GetGuid(8),r.IsDBNull(9)?null:r.GetString(9),r.IsDBNull(10)?null:r.GetString(10),r.IsDBNull(11)?null:r.GetInt32(11),r.IsDBNull(12)?"":r.GetString(12),null,available,reason));}
        return ServiceResult<IReadOnlyList<SuitableDriverDto>>.Ok(list);
    }

    public async Task<ServiceResult<TripOperationsDetailDto>> AssignAsync(Guid actor,Guid bookingId,AssignTripRequest request,bool isSuperAdmin,CancellationToken ct)
    {
        await using var cn=Open();await cn.OpenAsync(ct);await using var tx=await cn.BeginTransactionAsync(ct);
        var validation=await ValidateAssignmentAsync(cn,tx,bookingId,request.DriverProfileId,request.VehicleId,ct);if(validation is not null)return ServiceResult<TripOperationsDetailDto>.Fail(409,"assignment_invalid",validation);
        await LockBookingAsync(cn,tx,bookingId,ct);
        await ExecAsync(cn,tx,"update udrive.trip_assignments set status='Replaced',ended_at=now(),end_reason='Reassigned by operations',updated_at=now(),version=version+1 where booking_id=@booking and status='Active'",ct,("booking",bookingId));
        await ExecAsync(cn,tx,@"insert into udrive.trip_assignments(id,booking_id,driver_profile_id,vehicle_id,assignment_type,status,assigned_by_user_id,assignment_notes,created_at,updated_at) values(gen_random_uuid(),@booking,@driver,@vehicle,@type,'Active',@actor,@notes,now(),now())",ct,("booking",bookingId),("driver",request.DriverProfileId),("vehicle",request.VehicleId),("type",request.EmergencyReplacement?"EmergencyReplacement":"Primary"),("actor",actor),("notes",request.Notes));
        await ExecAsync(cn,tx,"update udrive.bookings set driver_profile_id=@driver,vehicle_id=@vehicle,status='DriverAssigned',updated_at=now(),version=version+1 where id=@booking",ct,("driver",request.DriverProfileId),("vehicle",request.VehicleId),("booking",bookingId));
        await ExecAsync(cn,tx,"update udrive.trip_operations set operational_status='DriverAssigned',trip_status='DriverAssigned',last_activity_at=now(),updated_at=now(),version=version+1 where booking_id=@booking",ct,("booking",bookingId));
        await HistoryAsync(cn,tx,bookingId,null,"DriverAssigned",actor,"Admin",request.Notes,ct);await NotifyBookingPartiesAsync(cn,tx,bookingId,"DriverAssigned","Driver assigned","A verified driver and vehicle have been assigned to your booking.",ct);await AuditAsync(cn,tx,actor,"trip.assignment.created","Booking",bookingId.ToString(),request,ct);await tx.CommitAsync(ct);
        return ServiceResult<TripOperationsDetailDto>.Ok((await LoadDetailAsync(cn,bookingId,ct))!);
    }

    public async Task<ServiceResult<OperationsDriverOfferDto>> SendOfferAsync(Guid actor,Guid bookingId,SendDriverBookingOfferRequest request,CancellationToken ct)
    {
        await using var cn=Open();await cn.OpenAsync(ct);await using var tx=await cn.BeginTransactionAsync(ct);
        var validation=await ValidateAssignmentAsync(cn,tx,bookingId,request.DriverProfileId,request.VehicleId,ct);if(validation is not null)return ServiceResult<OperationsDriverOfferDto>.Fail(409,"offer_invalid",validation);
        await ExpireOffersAsync(cn,tx,ct);var id=Guid.NewGuid();var expiry=DateTimeOffset.UtcNow.AddMinutes(request.ExpiresInMinutes);
        try{await ExecAsync(cn,tx,@"insert into udrive.driver_booking_offers(id,booking_id,driver_profile_id,vehicle_id,offered_by_user_id,status,expires_at,offer_notes,created_at,updated_at) values(@id,@booking,@driver,@vehicle,@actor,'Pending',@expiry,@notes,now(),now())",ct,("id",id),("booking",bookingId),("driver",request.DriverProfileId),("vehicle",request.VehicleId),("actor",actor),("expiry",expiry),("notes",request.Notes));}
        catch(PostgresException ex) when(ex.SqlState==PostgresErrorCodes.UniqueViolation){return ServiceResult<OperationsDriverOfferDto>.Fail(409,"duplicate_offer","A pending offer already exists for this driver.");}
        await ExecAsync(cn,tx,"update udrive.trip_operations set operational_status='OfferSent',last_activity_at=now(),updated_at=now(),version=version+1 where booking_id=@booking",ct,("booking",bookingId));
        await NotifyDriverAsync(cn,tx,request.DriverProfileId,"BookingOffer","New booking offer","A new trip offer is waiting for your response.",bookingId,ct);await AuditAsync(cn,tx,actor,"trip.offer.sent","DriverBookingOffer",id.ToString(),request,ct);await tx.CommitAsync(ct);
        var name=await ScalarStringAsync(cn,"select u.full_name from udrive.driver_profiles d join udrive.users u on u.id=d.user_id where d.id=@id",ct,("id",request.DriverProfileId))??"Driver";var vehicle=await ScalarStringAsync(cn,"select concat(make,' ',model,' · ',registration_number) from udrive.vehicles where id=@id",ct,("id",request.VehicleId));
        return ServiceResult<OperationsDriverOfferDto>.Created(new(id,request.DriverProfileId,name,vehicle,"Pending",expiry,null,request.Notes,DateTimeOffset.UtcNow));
    }

    public async Task<ServiceResult<bool>> RespondOfferAsync(Guid actor,Guid offerId,RespondDriverBookingOfferRequest request,CancellationToken ct)
    {
        await using var cn=Open();await cn.OpenAsync(ct);await using var tx=await cn.BeginTransactionAsync(ct);await ExpireOffersAsync(cn,tx,ct);
        const string select=@"select o.booking_id,o.driver_profile_id,o.vehicle_id,o.status,o.expires_at from udrive.driver_booking_offers o join udrive.driver_profiles dp on dp.id=o.driver_profile_id where o.id=@id and dp.user_id=@actor for update";
        Guid booking,driver,vehicle;string status;DateTimeOffset expires;await using(var cmd=new NpgsqlCommand(select,cn,tx)){cmd.Parameters.AddWithValue("id",offerId);cmd.Parameters.AddWithValue("actor",actor);await using var r=await cmd.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return ServiceResult<bool>.Fail(404,"offer_not_found","Offer not found.");booking=r.GetGuid(0);driver=r.GetGuid(1);vehicle=r.GetGuid(2);status=r.GetString(3);expires=r.GetFieldValue<DateTimeOffset>(4);}if(status!="Pending"||expires<=DateTimeOffset.UtcNow)return ServiceResult<bool>.Fail(409,"offer_closed","This offer is no longer active.");
        if(request.Decision.Equals("Reject",StringComparison.OrdinalIgnoreCase)){await ExecAsync(cn,tx,"update udrive.driver_booking_offers set status='Rejected',responded_at=now(),rejection_reason=@reason,updated_at=now(),version=version+1 where id=@id",ct,("reason",request.RejectionReason),("id",offerId));await ExecAsync(cn,tx,"update udrive.trip_operations set operational_status='DriverRejected',last_activity_at=now(),updated_at=now(),version=version+1 where booking_id=@booking",ct,("booking",booking));await NotifyAdminsAsync(cn,tx,"DriverRejected","Driver rejected booking offer",request.RejectionReason??"The driver rejected the booking offer.",booking,ct);await AuditAsync(cn,tx,actor,"trip.offer.rejected","DriverBookingOffer",offerId.ToString(),request,ct);await tx.CommitAsync(ct);return ServiceResult<bool>.Ok(true);}
        var validation=await ValidateAssignmentAsync(cn,tx,booking,driver,vehicle,ct);if(validation is not null)return ServiceResult<bool>.Fail(409,"assignment_invalid",validation);
        await ExecAsync(cn,tx,"update udrive.driver_booking_offers set status='Accepted',responded_at=now(),updated_at=now(),version=version+1 where id=@id",ct,("id",offerId));await ExecAsync(cn,tx,"update udrive.driver_booking_offers set status='Withdrawn',updated_at=now(),version=version+1 where booking_id=@booking and id<>@id and status='Pending'",ct,("booking",booking),("id",offerId));
        await ExecAsync(cn,tx,@"insert into udrive.trip_assignments(id,booking_id,driver_profile_id,vehicle_id,assignment_type,status,assigned_by_user_id,accepted_at,created_at,updated_at) values(gen_random_uuid(),@booking,@driver,@vehicle,'OfferAccepted','Active',@actor,now(),now(),now()) on conflict do nothing",ct,("booking",booking),("driver",driver),("vehicle",vehicle),("actor",actor));
        await ExecAsync(cn,tx,"update udrive.bookings set driver_profile_id=@driver,vehicle_id=@vehicle,status='DriverAssigned',updated_at=now(),version=version+1 where id=@booking",ct,("driver",driver),("vehicle",vehicle),("booking",booking));await ExecAsync(cn,tx,"update udrive.trip_operations set operational_status='DriverAccepted',trip_status='DriverAccepted',driver_accepted_at=now(),last_activity_at=now(),updated_at=now(),version=version+1 where booking_id=@booking",ct,("booking",booking));await HistoryAsync(cn,tx,booking,"DriverAssigned","DriverAccepted",actor,"Driver",null,ct);await NotifyBookingPartiesAsync(cn,tx,booking,"DriverAccepted","Driver accepted","Your assigned driver accepted the trip.",ct);await AuditAsync(cn,tx,actor,"trip.offer.accepted","DriverBookingOffer",offerId.ToString(),request,ct);await tx.CommitAsync(ct);return ServiceResult<bool>.Ok(true);
    }

    public async Task<ServiceResult<TripOperationsDetailDto>> ChangeStatusAsync(Guid actor,string source,bool superAdmin,Guid bookingId,ChangeTripStatusRequest request,CancellationToken ct)
    {
        await using var cn=Open();await cn.OpenAsync(ct);await using var tx=await cn.BeginTransactionAsync(ct);var current=await CurrentStateAsync(cn,tx,bookingId,ct);if(current is null)return ServiceResult<TripOperationsDetailDto>.Fail(404,"booking_not_found","Booking not found.");
        if(request.ExpectedVersion.HasValue&&request.ExpectedVersion.Value!=current.Value.Version)return ServiceResult<TripOperationsDetailDto>.Fail(409,"version_conflict","The trip changed. Refresh and try again.");
        if(!CanTransition(current.Value.Status,request.Status,request.Override&&superAdmin))return ServiceResult<TripOperationsDetailDto>.Fail(409,"invalid_transition",$"Trip cannot change from {current.Value.Status} to {request.Status}.");
        if(source=="Driver"&&!await DriverOwnsBookingAsync(cn,tx,actor,bookingId,ct))return ServiceResult<TripOperationsDetailDto>.Fail(403,"not_assigned","You are not the assigned driver.");
        if(source=="Customer"&&!await CustomerOwnsBookingAsync(cn,tx,actor,bookingId,ct))return ServiceResult<TripOperationsDetailDto>.Fail(403,"not_owner","You do not own this booking.");
        if(request.Status=="TripStarted"&&!await HasAcceptedAssignmentAsync(cn,tx,bookingId,ct))return ServiceResult<TripOperationsDetailDto>.Fail(409,"driver_not_accepted","Trip cannot start until the assigned verified driver accepts.");
        if(source=="Driver"&&request.Status=="TripStarted")
        {
            var suppliedOtp=(request.TripOtp??string.Empty).Trim();
            if(suppliedOtp.Length!=4||!suppliedOtp.All(char.IsDigit))
                return ServiceResult<TripOperationsDetailDto>.Fail(400,"trip_otp_required","Enter the Customer's 4-digit Trip OTP to start the ride.");
            var storedHash=await ScalarStringAsync(cn,"select trip_otp_hash from udrive.bookings where id=@id",ct,tx,("id",bookingId));
            var suppliedHash=SecurityHashing.HashWithSecret(suppliedOtp,authOptions.OtpHashSecret);
            if(string.IsNullOrWhiteSpace(storedHash)||!string.Equals(storedHash,suppliedHash,StringComparison.Ordinal))
                return ServiceResult<TripOperationsDetailDto>.Fail(409,"invalid_trip_otp","The Trip OTP is incorrect. Ask the Customer for the code shown in their app.");
        }
        var timeColumn=request.Status switch{"DriverEnRoute"=>"en_route_at","DriverArrived"=>"arrived_at","TripStarted"=>"started_at","TripCompleted"=>"completed_at","Cancelled"=>"cancelled_at","Emergency"=>"emergency_raised_at",_=>null};
        var sql="update udrive.trip_operations set trip_status=@status,operational_status=@operational,last_activity_at=now(),updated_at=now(),version=version+1"+(timeColumn is null?"":$",{timeColumn}=now()")+" where booking_id=@booking";var operational=request.Status switch{"DriverAccepted"=>"DriverAccepted","Cancelled"=>"Cancelled","TripCompleted"=>"Completed","Emergency"=>"Emergency","Disputed"=>"Disputed","ReassignmentRequired"=>"ReassignmentRequired",_=>current.Value.Operational};await ExecAsync(cn,tx,sql,ct,("status",request.Status),("operational",operational),("booking",bookingId));
        var legacy=request.Status switch{"TripStarted"=>"InProgress","TripCompleted"=>"Completed",_=>request.Status};await ExecAsync(cn,tx,"update udrive.bookings set status=@status,updated_at=now(),version=version+1 where id=@booking",ct,("status",legacy),("booking",bookingId));
        // The platform's share comes out when the trip is finished, not when it
        // is accepted — a booking that never happened should not cost the
        // Driver anything. Inside this transaction, so the charge and the
        // completion commit together or neither does, and keyed on the booking
        // so a retried completion cannot charge twice.
        if(request.Status=="TripCompleted"){await DriverWalletService.ChargeCommissionAsync(cn,tx,bookingId,ct);}
        // Abandoning a ride already accepted costs the Driver 2% of the fare —
        // but only before the trip starts. Once the Customer is in the vehicle
        // a cancellation is a different and more serious event, and belongs
        // with disputes rather than an automatic fee. `source` distinguishes
        // the Driver's own cancellation from an Admin or Customer one.
        if(request.Status=="Cancelled"&&source=="Driver"&&current.Value.Status!="TripStarted"){await DriverWalletService.ChargeCancellationAsync(cn,tx,bookingId,ct);}await HistoryAsync(cn,tx,bookingId,current.Value.Status,request.Status,actor,source,request.Reason,ct);var notification=request.Status switch{"DriverEnRoute"=>("DriverOnTheWay","Your Driver is on the way","Your Driver has started travelling to your pickup location. Open live tracking to follow the vehicle."),"DriverArrived"=>("DriverArrived","Your Driver has arrived","Your Driver is waiting at the pickup location."),"TripStarted"=>("TripStarted","Your trip has started","Your trip is now in progress."),"TripCompleted"=>("TripCompleted","Trip completed","Your trip has been completed successfully."),_=> (request.Status,$"Trip status: {request.Status}",request.Reason??$"Trip status changed to {request.Status}.")};await NotifyBookingPartiesAsync(cn,tx,bookingId,notification.Item1,notification.Item2,notification.Item3,ct);await AuditAsync(cn,tx,actor,"trip.status.changed","Booking",bookingId.ToString(),request,ct);await tx.CommitAsync(ct);return ServiceResult<TripOperationsDetailDto>.Ok((await LoadDetailAsync(cn,bookingId,ct))!);
    }

    public async Task<ServiceResult<TripNoteDto>> AddNoteAsync(Guid actor,Guid bookingId,AddTripNoteRequest request,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);var id=Guid.NewGuid();await ExecAsync(cn,null,"insert into udrive.trip_notes(id,booking_id,author_user_id,note_type,note,is_customer_visible,created_at,updated_at) values(@id,@booking,@actor,@type,@note,@visible,now(),now())",ct,("id",id),("booking",bookingId),("actor",actor),("type",request.NoteType),("note",request.Note),("visible",request.IsCustomerVisible));var author=await ScalarStringAsync(cn,"select full_name from udrive.users where id=@id",ct,("id",actor))??"Admin";return ServiceResult<TripNoteDto>.Created(new(id,request.NoteType,request.Note,author,request.IsCustomerVisible,DateTimeOffset.UtcNow));}
    public async Task<ServiceResult<bool>> RescheduleAsync(Guid actor,Guid bookingId,RescheduleTripRequest request,CancellationToken ct){if(request.ReturnAt.HasValue&&request.ReturnAt<=request.PickupAt)return ServiceResult<bool>.Fail(400,"invalid_dates","Return time must be after pickup time.");await using var cn=Open();await cn.OpenAsync(ct);await using var tx=await cn.BeginTransactionAsync(ct);await ExecAsync(cn,tx,"update udrive.bookings set pickup_at=@pickup,return_at=@return,updated_at=now(),version=version+1 where id=@id",ct,("pickup",request.PickupAt),("return",request.ReturnAt),("id",bookingId));await ExecAsync(cn,tx,"update udrive.trip_operations set pickup_at=@pickup,return_at=@return,last_activity_at=now(),updated_at=now(),version=version+1 where booking_id=@id",ct,("pickup",request.PickupAt),("return",request.ReturnAt),("id",bookingId));await AuditAsync(cn,tx,actor,"trip.rescheduled","Booking",bookingId.ToString(),request,ct);await tx.CommitAsync(ct);return ServiceResult<bool>.Ok(true);}

    public async Task<ServiceResult<IReadOnlyList<DriverTripOfferDto>>> DriverOffersAsync(Guid userId,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);await ExpireOffersAsync(cn,null,ct);const string sql=@"select o.id,b.id,b.booking_reference,cu.full_name,coalesce(b.pickup_label,''),coalesce(b.destination_label,''),b.pickup_at,b.seats_booked,b.booking_type,concat(v.make,' ',v.model),v.registration_number,o.expires_at,o.offer_notes from udrive.driver_booking_offers o join udrive.driver_profiles dp on dp.id=o.driver_profile_id join udrive.bookings b on b.id=o.booking_id join udrive.users cu on cu.id=b.customer_user_id join udrive.vehicles v on v.id=o.vehicle_id where dp.user_id=@user and o.status='Pending' and o.expires_at>now() order by b.pickup_at";var list=new List<DriverTripOfferDto>();await using var cmd=new NpgsqlCommand(sql,cn);cmd.Parameters.AddWithValue("user",userId);await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetFieldValue<DateTimeOffset>(6),r.GetInt32(7),r.GetString(8),r.GetString(9),r.GetString(10),r.GetFieldValue<DateTimeOffset>(11),r.IsDBNull(12)?null:r.GetString(12)));return ServiceResult<IReadOnlyList<DriverTripOfferDto>>.Ok(list);}
    public async Task<ServiceResult<IReadOnlyList<MobileTripDto>>> DriverTripsAsync(Guid userId,CancellationToken ct)=>ServiceResult<IReadOnlyList<MobileTripDto>>.Ok(await MobileTripsAsync(userId,true,ct));
    public async Task<ServiceResult<IReadOnlyList<MobileTripDto>>> CustomerTripsAsync(Guid userId,CancellationToken ct)=>ServiceResult<IReadOnlyList<MobileTripDto>>.Ok(await MobileTripsAsync(userId,false,ct));

    private async Task<IReadOnlyList<MobileTripDto>> MobileTripsAsync(Guid userId,bool driver,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);var where=driver?"dp.user_id=@user":"b.customer_user_id=@user";var sql=$@"select b.id,b.booking_reference,cu.full_name,cu.phone_number,du.full_name,du.phone_number,case when v.id is null then null else concat(v.make,' ',v.model) end,v.registration_number,coalesce(b.pickup_label,''),coalesce(b.destination_label,''),o.pickup_at,o.return_at,b.seats_booked,b.booking_type,b.total_amount,b.payment_status,o.trip_status,o.operational_status,b.special_instructions,o.last_activity_at from udrive.bookings b join udrive.trip_operations o on o.booking_id=b.id join udrive.users cu on cu.id=b.customer_user_id left join udrive.driver_profiles dp on dp.id=b.driver_profile_id left join udrive.users du on du.id=dp.user_id left join udrive.vehicles v on v.id=b.vehicle_id where {where} order by case when o.trip_status in ('TripCompleted','Cancelled') then 1 else 0 end,o.pickup_at";var list=new List<MobileTripDto>();await using var cmd=new NpgsqlCommand(sql,cn);cmd.Parameters.AddWithValue("user",userId);await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetString(3),r.IsDBNull(4)?null:r.GetString(4),r.IsDBNull(5)?null:r.GetString(5),r.IsDBNull(6)?null:r.GetString(6),r.IsDBNull(7)?null:r.GetString(7),r.GetString(8),r.GetString(9),r.GetFieldValue<DateTimeOffset>(10),r.IsDBNull(11)?null:r.GetFieldValue<DateTimeOffset>(11),r.GetInt32(12),r.GetString(13),r.GetDecimal(14),r.GetString(15),r.GetString(16),r.GetString(17),r.IsDBNull(18)?null:r.GetString(18),r.GetFieldValue<DateTimeOffset>(19)));return list;}

    private static bool CanTransition(string from,string to,bool force)=>force||from.Equals(to,StringComparison.OrdinalIgnoreCase)||(AllowedTransitions.TryGetValue(from,out var allowed)&&allowed.Contains(to));
    private static async Task LockBookingAsync(NpgsqlConnection cn,NpgsqlTransaction tx,Guid bookingId,CancellationToken ct)=>_ = await ScalarStringAsync(cn,"select id::text from udrive.bookings where id=@id for update",ct,tx,("id",bookingId));
    private static async Task<(string Status,string Operational,int Version)?> CurrentStateAsync(NpgsqlConnection cn,NpgsqlTransaction tx,Guid id,CancellationToken ct){await using var cmd=new NpgsqlCommand("select trip_status,operational_status,version from udrive.trip_operations where booking_id=@id for update",cn,tx);cmd.Parameters.AddWithValue("id",id);await using var r=await cmd.ExecuteReaderAsync(ct);return await r.ReadAsync(ct)?(r.GetString(0),r.GetString(1),r.GetInt32(2)):null;}
