    private static async Task<bool> HasAcceptedAssignmentAsync(NpgsqlConnection cn,NpgsqlTransaction tx,Guid booking,CancellationToken ct)=>await ScalarIntAsync(cn,"select count(*) from udrive.trip_assignments a join udrive.driver_profiles d on d.id=a.driver_profile_id join udrive.vehicles v on v.id=a.vehicle_id where a.booking_id=@booking and a.status='Active' and lower(d.verification_status) in ('approved','verified') and lower(v.status) in ('verified','approved') and (a.accepted_at is not null or a.assignment_type='Primary')",ct,tx,("booking",booking))>0;

    private static async Task<string?> ValidateAssignmentAsync(NpgsqlConnection cn,NpgsqlTransaction tx,Guid booking,Guid driver,Guid vehicle,CancellationToken ct){const string sql=@"select dp.verification_status,u.status,v.status,v.passenger_capacity,b.seats_booked,(v.driver_profile_id=dp.id),exists(select 1 from udrive.trip_assignments a join udrive.trip_operations ox on ox.booking_id=a.booking_id join udrive.trip_operations target on target.booking_id=@booking where a.status='Active' and a.booking_id<>@booking and (a.driver_profile_id=@driver or a.vehicle_id=@vehicle) and ox.trip_status not in ('TripCompleted','Cancelled','NoShow') and tstzrange(ox.pickup_at,coalesce(ox.return_at,ox.pickup_at+interval '8 hours'),'[]') && tstzrange(target.pickup_at,coalesce(target.return_at,target.pickup_at+interval '8 hours'),'[]')) from udrive.bookings b join udrive.driver_profiles dp on dp.id=@driver join udrive.users u on u.id=dp.user_id join udrive.vehicles v on v.id=@vehicle where b.id=@booking";await using var cmd=new NpgsqlCommand(sql,cn,tx);cmd.Parameters.AddWithValue("booking",booking);cmd.Parameters.AddWithValue("driver",driver);cmd.Parameters.AddWithValue("vehicle",vehicle);await using var r=await cmd.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return "Driver, vehicle, or booking was not found.";if(!string.Equals(r.GetString(0),"Approved",StringComparison.OrdinalIgnoreCase)&&!string.Equals(r.GetString(0),"Verified",StringComparison.OrdinalIgnoreCase))return "Driver must be verified and approved.";if(r.GetString(1) is "Suspended" or "Rejected")return "Driver account is suspended or rejected.";if(!string.Equals(r.GetString(2),"Verified",StringComparison.OrdinalIgnoreCase)&&!string.Equals(r.GetString(2),"Approved",StringComparison.OrdinalIgnoreCase))return "Vehicle must be verified.";if(!r.GetBoolean(5))return "Selected vehicle does not belong to this driver.";if(r.GetInt32(3)<r.GetInt32(4))return "Vehicle passenger capacity is insufficient.";if(r.GetBoolean(6))return "Driver or vehicle has an overlapping active booking.";return null;}

    private static async Task<OperationsSummaryDto> SummaryAsync(NpgsqlConnection cn,CancellationToken ct){const string sql=@"select count(*) filter(where pickup_at>=now() and trip_status not in ('TripCompleted','Cancelled')),count(*) filter(where operational_status in ('PendingAssignment','ReassignmentRequired')),count(*) filter(where operational_status='OfferSent'),count(*) filter(where trip_status in ('DriverAccepted','DriverEnRoute','DriverArrived','TripStarted')),count(*) filter(where trip_status='TripCompleted'),count(*) filter(where trip_status='Cancelled'),count(*) filter(where trip_status='Emergency'),count(*) filter(where trip_status='Disputed') from udrive.trip_operations";await using var cmd=new NpgsqlCommand(sql,cn);await using var r=await cmd.ExecuteReaderAsync(ct);await r.ReadAsync(ct);return new(r.GetInt32(0),r.GetInt32(1),r.GetInt32(2),r.GetInt32(3),r.GetInt32(4),r.GetInt32(5),r.GetInt32(6),r.GetInt32(7));}
    private static async Task<PagedResult<OperationsBookingDto>> QueryBookingsAsync(NpgsqlConnection cn,string? search,string? status,string? payment,string? city,DateTimeOffset? from,DateTimeOffset? to,int page,int pageSize,CancellationToken ct){var where=@"where (@search is null or b.booking_reference ilike '%'||@search||'%' or cu.full_name ilike '%'||@search||'%' or du.full_name ilike '%'||@search||'%' or v.registration_number ilike '%'||@search||'%') and (@status is null or o.trip_status=@status or o.operational_status=@status) and (@payment is null or b.payment_status=@payment) and (@city is null or b.pickup_label ilike '%'||@city||'%' or b.destination_label ilike '%'||@city||'%') and (@from is null or o.pickup_at>=@from) and (@to is null or o.pickup_at<=@to)";var count=await ScalarIntAsync(cn,"select count(*) from udrive.bookings b join udrive.trip_operations o on o.booking_id=b.id join udrive.users cu on cu.id=b.customer_user_id left join udrive.driver_profiles dp on dp.id=b.driver_profile_id left join udrive.users du on du.id=dp.user_id left join udrive.vehicles v on v.id=b.vehicle_id "+where,ct,null,("search",search),("status",status),("payment",payment),("city",city),("from",from),("to",to));var sql=@"select b.id,b.booking_reference,cu.full_name,cu.phone_number,du.full_name,du.phone_number,case when v.id is null then null else concat(v.make,' ',v.model) end,v.registration_number,b.pickup_label,b.destination_label,o.pickup_at,o.return_at,b.booking_type,b.seats_booked,b.payment_status,o.trip_status,o.operational_status,o.last_activity_at,(o.trip_status='Emergency') from udrive.bookings b join udrive.trip_operations o on o.booking_id=b.id join udrive.users cu on cu.id=b.customer_user_id left join udrive.driver_profiles dp on dp.id=b.driver_profile_id left join udrive.users du on du.id=dp.user_id left join udrive.vehicles v on v.id=b.vehicle_id "+where+" order by o.last_activity_at desc limit @limit offset @offset";var list=new List<OperationsBookingDto>();await using var cmd=new NpgsqlCommand(sql,cn);AddParams(cmd,("search",search),("status",status),("payment",payment),("city",city),("from",from),("to",to),("limit",pageSize),("offset",(page-1)*pageSize));await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(MapBooking(r));return new(list,page,pageSize,count,(int)Math.Ceiling(count/(double)pageSize));}
    private static OperationsBookingDto MapBooking(NpgsqlDataReader r)=>new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetString(3),r.IsDBNull(4)?null:r.GetString(4),r.IsDBNull(5)?null:r.GetString(5),r.IsDBNull(6)?null:r.GetString(6),r.IsDBNull(7)?null:r.GetString(7),r.IsDBNull(8)?null:r.GetString(8),r.IsDBNull(9)?null:r.GetString(9),r.GetFieldValue<DateTimeOffset>(10),r.IsDBNull(11)?null:r.GetFieldValue<DateTimeOffset>(11),r.GetString(12),r.GetInt32(13),r.GetString(14),r.GetString(15),r.GetString(16),r.GetFieldValue<DateTimeOffset>(17),r.GetBoolean(18));

    private static async Task<TripOperationsDetailDto?> LoadDetailAsync(NpgsqlConnection cn,Guid bookingId,CancellationToken ct){const string sql=@"select b.id,b.booking_reference,cu.full_name,cu.phone_number,du.full_name,du.phone_number,case when v.id is null then null else concat(v.make,' ',v.model) end,v.registration_number,b.pickup_label,b.destination_label,o.pickup_at,o.return_at,b.booking_type,b.seats_booked,b.payment_status,o.trip_status,o.operational_status,o.last_activity_at,(o.trip_status='Emergency'),cu.id,cu.email,dp.id,du.id,du.email,v.id,v.make,v.model,v.category,v.passenger_capacity,v.status,tp.title,b.total_amount,b.special_instructions,b.emergency_contact_name,b.emergency_contact_phone,o.version from udrive.bookings b join udrive.trip_operations o on o.booking_id=b.id join udrive.users cu on cu.id=b.customer_user_id left join udrive.driver_profiles dp on dp.id=b.driver_profile_id left join udrive.users du on du.id=dp.user_id left join udrive.vehicles v on v.id=b.vehicle_id left join udrive.tour_packages tp on tp.id=b.tour_package_id where b.id=@id";await using var cmd=new NpgsqlCommand(sql,cn);cmd.Parameters.AddWithValue("id",bookingId);OperationsBookingDto booking;TripPersonDto customer;TripPersonDto? driver;TripVehicleDto? vehicle;string? package;decimal fare;string? instructions;string? emergency;int version;await using(var r=await cmd.ExecuteReaderAsync(ct)){if(!await r.ReadAsync(ct))return null;booking=MapBooking(r);customer=new(r.GetGuid(19),r.GetString(2),r.GetString(3),r.IsDBNull(20)?null:r.GetString(20));driver=r.IsDBNull(22)?null:new(r.GetGuid(22),r.GetString(4),r.GetString(5),r.IsDBNull(23)?null:r.GetString(23));vehicle=r.IsDBNull(24)?null:new(r.GetGuid(24),r.GetString(25),r.GetString(26),r.GetString(7),r.GetString(27),r.GetInt32(28),r.GetString(29));package=r.IsDBNull(30)?null:r.GetString(30);fare=r.GetDecimal(31);instructions=r.IsDBNull(32)?null:r.GetString(32);emergency=r.IsDBNull(33)&&r.IsDBNull(34)?null:$"{(r.IsDBNull(33)?"":r.GetString(33))} {(r.IsDBNull(34)?"":r.GetString(34))}".Trim();version=r.GetInt32(35);}var timeline=new List<TripTimelineDto>();await using(var h=new NpgsqlCommand("select h.to_status,h.from_status,h.source,h.reason,u.full_name,h.created_at from udrive.trip_status_history h left join udrive.users u on u.id=h.changed_by_user_id where h.booking_id=@id order by h.created_at",cn)){h.Parameters.AddWithValue("id",bookingId);await using var r=await h.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))timeline.Add(new(r.GetString(0),r.IsDBNull(1)?null:r.GetString(1),r.GetString(2),r.IsDBNull(3)?null:r.GetString(3),r.IsDBNull(4)?null:r.GetString(4),r.GetFieldValue<DateTimeOffset>(5)));}var notes=new List<TripNoteDto>();await using(var n=new NpgsqlCommand("select n.id,n.note_type,n.note,u.full_name,n.is_customer_visible,n.created_at from udrive.trip_notes n join udrive.users u on u.id=n.author_user_id where n.booking_id=@id order by n.created_at desc",cn)){n.Parameters.AddWithValue("id",bookingId);await using var r=await n.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))notes.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetBoolean(4),r.GetFieldValue<DateTimeOffset>(5)));}var offers=new List<OperationsDriverOfferDto>();await using(var o=new NpgsqlCommand("select x.id,x.driver_profile_id,u.full_name,concat(v.make,' ',v.model,' · ',v.registration_number),x.status,x.expires_at,x.rejection_reason,x.offer_notes,x.created_at from udrive.driver_booking_offers x join udrive.driver_profiles d on d.id=x.driver_profile_id join udrive.users u on u.id=d.user_id join udrive.vehicles v on v.id=x.vehicle_id where x.booking_id=@id order by x.created_at desc",cn)){o.Parameters.AddWithValue("id",bookingId);await using var r=await o.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))offers.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetFieldValue<DateTimeOffset>(5),r.IsDBNull(6)?null:r.GetString(6),r.IsDBNull(7)?null:r.GetString(7),r.GetFieldValue<DateTimeOffset>(8)));}return new(booking,customer,driver,vehicle,package,fare,instructions,emergency,timeline,notes,offers,version);}

