    private static async Task AuditAsync(NpgsqlConnection cn,NpgsqlTransaction tx,Guid actor,string action,string type,string entity,object changes,CancellationToken ct)=>await ExecAsync(cn,tx,"insert into udrive.audit_logs(id,actor_user_id,action,entity_type,entity_id,changes_json,created_at,updated_at) values(gen_random_uuid(),@actor,@action,@type,@entity,cast(@changes as jsonb),now(),now())",ct,("actor",actor),("action",action),("type",type),("entity",entity),("changes",JsonSerializer.Serialize(changes)));
    private static async Task<int> ExecAsync(NpgsqlConnection cn,NpgsqlTransaction? tx,string sql,CancellationToken ct,params (string,object?)[] values){await using var cmd=new NpgsqlCommand(sql,cn,tx);AddParams(cmd,values);return await cmd.ExecuteNonQueryAsync(ct);}
    private static void AddParams(NpgsqlCommand cmd,params (string,object?)[] values){foreach(var (name,value) in values){if(value is null){var type=name is "from" or "to" or "return" ? NpgsqlDbType.TimestampTz : name is "actor" ? NpgsqlDbType.Uuid : NpgsqlDbType.Text;cmd.Parameters.Add(new NpgsqlParameter(name,type){Value=DBNull.Value});}else cmd.Parameters.AddWithValue(name,value);}}
    private static async Task<int> ScalarIntAsync(NpgsqlConnection cn,string sql,CancellationToken ct,NpgsqlTransaction? tx=null,params (string,object?)[] values){await using var cmd=new NpgsqlCommand(sql,cn,tx);AddParams(cmd,values);return Convert.ToInt32(await cmd.ExecuteScalarAsync(ct)??0);}
    private static async Task<string?> ScalarStringAsync(NpgsqlConnection cn,string sql,CancellationToken ct,params (string,object?)[] values)=>await ScalarStringAsync(cn,sql,ct,null,values);
    private static async Task<string?> ScalarStringAsync(NpgsqlConnection cn,string sql,CancellationToken ct,NpgsqlTransaction? tx,params (string,object?)[] values){await using var cmd=new NpgsqlCommand(sql,cn,tx);AddParams(cmd,values);var x=await cmd.ExecuteScalarAsync(ct);return x is null or DBNull?null:Convert.ToString(x);}
